 if(C.events){var prev=-99;C.events.forEach(function(ev){var ex=xS(ev.i),crowded=(ex-prev)<58;prev=ex;svg.appendChild(el("line",{x1:ex,x2:ex,y1:m.t,y2:m.t+PH,stroke:"#1a3560","stroke-opacity":0.4,"stroke-dasharray":"2,3","stroke-width":1}));var an=ev.i>n*0.6?"end":"start",dx=an=="end"?-3:3,y0=m.t+10+(crowded?20:0);ev.t.forEach(function(L,li){svg.appendChild(tx("text",{x:ex+dx,y:y0+li*8,"text-anchor":an,"font-family":F,"font-size":7,"font-weight":700,fill:"#1a3560"},L));});});}
 C.series.forEach(function(s){var pts=[];for(var i=0;i<s.data.length;i++){if(s.data[i]!=null)pts.push([xS(i),yL(s.data[i])]);}var d=pts.map(function(q,i){return(i?"L":"M")+q[0].toFixed(1)+" "+q[1].toFixed(1);}).join(" ");svg.appendChild(el("path",{d:d,fill:"none",stroke:s.color,"stroke-width":s.width||2,"stroke-dasharray":s.dash||"none","stroke-linejoin":"round","stroke-linecap":"round"}));if(s.label){var Lp=pts[pts.length-1];svg.appendChild(tx("text",{x:Lp[0]-4,y:Lp[1]-6,"text-anchor":"end","font-family":F,"font-size":7.5,"font-weight":700,fill:s.color},s.label));}if(pts.length){var ep=pts[pts.length-1];svg.appendChild(el("circle",{cx:ep[0],cy:ep[1],r:3.5,fill:s.color}));}});
 if(C.pill){var s=C.series[C.pill.si],lx=xS(n-1),ly=yL(s.data[n-1]),pw=C.pill.w||52,ph=16,px=lx-pw-6;if(px<m.l)px=m.l;var py=ly-ph/2;if(py<m.t)py=m.t+2;if(py+ph>m.t+PH)py=m.t+PH-ph-2;svg.appendChild(el("circle",{cx:lx,cy:ly,r:3.5,fill:C.pill.color||"#4a5568"}));svg.appendChild(el("rect",{x:px,y:py,width:pw,height:ph,rx:2,fill:"#e8a825"}));svg.appendChild(tx("text",{x:px+pw/2,y:py+ph/2+3.5,"text-anchor":"middle","font-family":F,"font-size":9,"font-weight":700,fill:"#111"},C.pill.text));}
 if(C.annot)C.annot.forEach(function(a){svg.appendChild(tx("text",{x:a.x,y:a.y,"text-anchor":a.anchor||"start","font-family":F,"font-size":a.size||8,"font-weight":a.weight||400,fill:a.fill||"#444"},a.t));});
